import re

def parse_size(text):
    pattern = r'^(\d+)B$|^(\d+)KB$|^(\d+)MB$|^(\d+)GB$'
    match = re.match(pattern, text)

    if match:
        num = int(match.group(1) or match.group(2) or match.group(3) or match.group(4))
        unit = match.group(1) and 'B' or match.group(2) and 'KB' or match.group(3) and 'MB' or match.group(4) and 'GB'

        if unit == 'B':
            return num
        elif unit == 'KB':
            return num * 1024
        elif unit == 'MB':
            return num * 1024**2
        elif unit == 'GB':
            return num * 1024**3
    else:
        raise ValueError("Invalid size format")

