def binary_search(xs, target):
    if not isinstance(xs, list):
        raise TypeError("xs must be a list")
    if not xs:
        return -1
    if not all(isinstance(x, (int, float)) for x in xs):
        raise TypeError("All elements in xs must be integers or floats")

    lo, hi = 0, len(xs) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if xs[mid] == target:
            return mid
        if xs[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

