import heapq

class TaskQueue:
    def __init__(self):
        self._queue = []
        self._entry_finder = {}  # mapping of tasks to entries
        self.REMOVED = '<removed-task>'  # placeholder for a removed task
        self._counter = iter(range(1000))  # use an iterator for the counter

    def add(self, name, priority=0):
        'Add a new task or update the priority of an existing task'
        if name in self._entry_finder:
            raise ValueError("Task already exists")
        count = next(self._counter)
        entry = [priority, count, name]
        self._entry_finder[name] = entry
        heapq.heappush(self._queue, entry)

    def pop(self):
        'Remove and return the lowest priority task. Raise IndexError if empty.'
        while self._queue:
            priority, count, name = heapq.heappop(self._queue)
            if name is not self.REMOVED:
                del self._entry_finder[name]
                return name
        raise IndexError('pop from an empty priority queue')

    def __len__(self):
        return len(self._entry_finder)

import heapq

class TaskQueue:
    def __init__(self):
        self._tasks = []
        self._task_names = set()

    def add(self, name, priority):
        if name in self._task_names:
            raise ValueError(f"Task '{name}' is already queued.")
        heapq.heappush(self._tasks, (priority, len(self._tasks), name))
        self._task_names.add(name)

    def pop(self):
        if not self._tasks:
            raise IndexError("Queue is empty.")
        priority, _, name = heapq.heappop(self._tasks)
        self._task_names.remove(name)
        return name

    def __len__(self):
        return len(self._tasks)
